<?php
session_start(); require_once __DIR__.'/conex.php'; header('Content-Type: application/json; charset=utf-8');
function resp($ok,$msg,$data=null){echo json_encode(['ok'=>$ok,'mensaje'=>$msg,'datos'=>$data],JSON_UNESCAPED_UNICODE);exit;}
function sesion(){if(empty($_SESSION['uid']))resp(false,'Sesión expirada. Inicia sesión nuevamente.');}
function rol($roles){sesion();if(!in_array((int)$_SESSION['rol'],$roles,true))resp(false,'Tu rol no tiene permiso para esta operación.');}
$op=$_POST['op']??$_GET['op']??'';
try{
 if($op==='login'){$mail=trim($_POST['correo']??'');$pass=$_POST['clave']??'';$st=$db->prepare('SELECT u.*,r.nombre_rol FROM usuarios u JOIN roles r ON r.id_rol=u.id_rol_fk WHERE u.correo=? AND u.activo=1 LIMIT 1');$st->bind_param('s',$mail);$st->execute();$u=$st->get_result()->fetch_assoc();if(!$u||!password_verify($pass,$u['clave']))resp(false,'Correo o contraseña incorrectos.');session_regenerate_id(true);$_SESSION['uid']=(int)$u['id_usuario'];$_SESSION['nombre']=$u['nombre'].' '.$u['apellido'];$_SESSION['rol']=(int)$u['id_rol_fk'];$_SESSION['rol_nombre']=$u['nombre_rol'];$_SESSION['programa']=$u['programa_formacion']??'';resp(true,'Bienvenido',['rol'=>$u['nombre_rol'],'id_rol'=>(int)$u['id_rol_fk']]);}
 if($op==='logout'){session_unset();session_destroy();resp(true,'Sesión cerrada.');}
 sesion();$uid=(int)$_SESSION['uid'];$role=(int)$_SESSION['rol'];
 if($op==='perfil')resp(true,'Perfil',['nombre'=>$_SESSION['nombre'],'rol'=>$_SESSION['rol_nombre'],'programa'=>$_SESSION['programa']??'','id_rol'=>$role]);
 if($op==='catalogos'){rol([1,2,3,4]);$wh=$db->query('SELECT id_bodega,nombre FROM bodegas WHERE activo=1 ORDER BY nombre')->fetch_all(MYSQLI_ASSOC);$items=$db->query('SELECT id_item,codigo,nombre,tipo,categoria,unidad,stock,stock_minimo,id_bodega_fk FROM inventario WHERE activo=1 ORDER BY nombre')->fetch_all(MYSQLI_ASSOC);resp(true,'Catalogos',['bodegas'=>$wh,'items'=>$items]);}
 if($op==='dashboard'){
  $cnt=function($sql)use($db){return (int)$db->query($sql)->fetch_assoc()['n'];};
  if($role===1){$stats=['inventario'=>$cnt('SELECT COUNT(*) n FROM inventario WHERE activo=1'),'stockBajo'=>$cnt('SELECT COUNT(*) n FROM inventario WHERE activo=1 AND stock<=stock_minimo'),'pendientes'=>$cnt("SELECT COUNT(*) n FROM solicitudes WHERE estado IN ('Pendiente','En revisión')"),'entregas'=>$cnt("SELECT COUNT(*) n FROM solicitudes WHERE estado='Entregada'")];}
  elseif($role===2){$st=$db->prepare('SELECT COUNT(*) n FROM solicitudes WHERE id_usuario_fk=?');$st->bind_param('i',$uid);$st->execute();$total=(int)$st->get_result()->fetch_assoc()['n'];$st=$db->prepare("SELECT COUNT(*) n FROM solicitudes WHERE id_usuario_fk=? AND estado='Pendiente'");$st->bind_param('i',$uid);$st->execute();$pend=(int)$st->get_result()->fetch_assoc()['n'];$stats=['misSolicitudes'=>$total,'pendientes'=>$pend];}
  elseif($role===3){$stats=['pendientes'=>$cnt("SELECT COUNT(*) n FROM solicitudes WHERE estado='Pendiente'"),'aprobadas'=>$cnt("SELECT COUNT(*) n FROM solicitudes WHERE estado='Aprobada'")];}
  else{$stats=['inventario'=>$cnt('SELECT COUNT(*) n FROM inventario WHERE activo=1'),'porEntregar'=>$cnt("SELECT COUNT(*) n FROM solicitudes WHERE estado='Aprobada'"),'stockBajo'=>$cnt('SELECT COUNT(*) n FROM inventario WHERE activo=1 AND stock<=stock_minimo')];}
  resp(true,'Resumen',$stats);
 }
 if($op==='listInventario'){rol([1,4]);$q='%'.trim($_GET['q']??'').'%';$st=$db->prepare('SELECT i.*,b.nombre bodega FROM inventario i JOIN bodegas b ON b.id_bodega=i.id_bodega_fk WHERE i.activo=1 AND (i.nombre LIKE ? OR i.codigo LIKE ? OR i.categoria LIKE ?) ORDER BY i.nombre');$st->bind_param('sss',$q,$q,$q);$st->execute();resp(true,'Inventario',$st->get_result()->fetch_all(MYSQLI_ASSOC));}
 if($op==='listSolicitudes'){rol([1,2,3,4]);$sql='SELECT s.*,u.nombre solicitante,u.apellido,u.programa_formacion,b.nombre bodega,r.nombre_rol rol_solicitante FROM solicitudes s JOIN usuarios u ON u.id_usuario=s.id_usuario_fk JOIN bodegas b ON b.id_bodega=s.id_bodega_fk JOIN roles r ON r.id_rol=u.id_rol_fk';if($role===2)$sql.=' WHERE s.id_usuario_fk='.$uid;$sql.=' ORDER BY s.id_solicitud DESC';$rows=$db->query($sql)->fetch_all(MYSQLI_ASSOC);foreach($rows as &$row){$st=$db->prepare('SELECT d.cantidad,d.cantidad_autorizada,d.observacion,i.nombre item,i.unidad,i.tipo,i.stock FROM solicitud_detalles d JOIN inventario i ON i.id_item=d.id_item_fk WHERE d.id_solicitud_fk=?');$st->bind_param('i',$row['id_solicitud']);$st->execute();$row['detalle']=$st->get_result()->fetch_all(MYSQLI_ASSOC);}resp(true,'Solicitudes',$rows);}
 if($op==='solicitudNueva'){rol([2]);$wh=(int)($_POST['bodega']??0);$just=trim($_POST['justificacion']??'');$date=$_POST['fecha']??'';$items=$_POST['items']??[];if(!$wh||strlen($just)<5||!is_array($items)||!count($items))resp(false,'Completa bodega, motivo y agrega al menos un artículo.');$check=$db->prepare('SELECT id_bodega FROM bodegas WHERE id_bodega=? AND activo=1');$check->bind_param('i',$wh);$check->execute();if(!$check->get_result()->fetch_assoc())resp(false,'La bodega seleccionada no es válida.');$db->begin_transaction();$st=$db->prepare("INSERT INTO solicitudes(codigo,id_usuario_fk,id_bodega_fk,justificacion,fecha_requerida) VALUES(NULL,?,?,?,NULLIF(?,''))");$st->bind_param('iiss',$uid,$wh,$just,$date);$st->execute();$sid=$st->insert_id;$code='SOL-'.str_pad((string)$sid,5,'0',STR_PAD_LEFT);$up=$db->prepare('UPDATE solicitudes SET codigo=? WHERE id_solicitud=?');$up->bind_param('si',$code,$sid);$up->execute();$det=$db->prepare('INSERT INTO solicitud_detalles(id_solicitud_fk,id_item_fk,cantidad) VALUES(?,?,?)');$count=0;foreach($items as $it){$id=(int)($it['id']??0);$qty=(float)($it['cantidad']??0);if($id<=0||$qty<=0)continue;$chk=$db->prepare('SELECT id_item FROM inventario WHERE id_item=? AND activo=1 AND id_bodega_fk=?');$chk->bind_param('ii',$id,$wh);$chk->execute();if(!$chk->get_result()->fetch_assoc())continue;$det->bind_param('iid',$sid,$id,$qty);$det->execute();$count++;}if(!$count){$db->rollback();resp(false,'No se agregaron artículos válidos para esa bodega.');}$db->commit();resp(true,'Solicitud enviada: '.$code,['codigo'=>$code]);}
 if($op==='crearItem'){rol([1,4]);$name=trim($_POST['nombre']??'');$type=$_POST['tipo']??'Insumo';$cat=trim($_POST['categoria']??'');$unit=trim($_POST['unidad']??'unidad');$stock=(float)($_POST['stock']??0);$min=(float)($_POST['minimo']??0);$wh=(int)($_POST['bodega']??0);$code=trim($_POST['codigo']??'');$loc=trim($_POST['ubicacion']??'');if(!$name||!$wh||$stock<0||$min<0||!in_array($type,['Insumo','Herramienta','Concentrado','Material','Otro'],true))resp(false,'Revisa nombre, tipo, bodega y cantidades.');$st=$db->prepare("INSERT INTO inventario(codigo,nombre,tipo,categoria,unidad,stock,stock_minimo,ubicacion,id_bodega_fk) VALUES(NULLIF(?,''),?,?,?,?,?,?,NULLIF(?,''),?)");$st->bind_param('sssssddsi',$code,$name,$type,$cat,$unit,$stock,$min,$loc,$wh);$st->execute();if($stock>0){$mov=$db->prepare("INSERT INTO movimientos(id_item_fk,id_usuario_fk,tipo,cantidad,detalle) VALUES(?,?,'Entrada',?,'Registro inicial')");$itemid=$st->insert_id;$mov->bind_param('iid',$itemid,$uid,$stock);$mov->execute();}resp(true,'Artículo registrado.');}
 if($op==='decisionSolicitud'){rol([1,3]);$sid=(int)($_POST['id']??0);$decision=$_POST['decision']??'';$obs=trim($_POST['observacion']??'');if(!$sid||!in_array($decision,['Aprobada','Rechazada'],true))resp(false,'Datos inválidos.');$st=$db->prepare("UPDATE solicitudes SET estado=?,observacion_coordinador=NULLIF(?,''),id_usuario_revisa_fk=?,fecha_actualizacion=NOW() WHERE id_solicitud=? AND estado IN ('Pendiente','En revisión')");$st->bind_param('ssii',$decision,$obs,$uid,$sid);$st->execute();if(!$st->affected_rows)resp(false,'Solicitud inexistente o ya revisada.');resp(true,'Solicitud '.$decision.'.');}
 if($op==='entregarSolicitud'){rol([1,4]);$sid=(int)($_POST['id']??0);$db->begin_transaction();$s=$db->prepare('SELECT estado FROM solicitudes WHERE id_solicitud=? FOR UPDATE');$s->bind_param('i',$sid);$s->execute();$row=$s->get_result()->fetch_assoc();if(!$row||$row['estado']!=='Aprobada'){$db->rollback();resp(false,'Solo se pueden entregar solicitudes aprobadas.');}$d=$db->prepare('SELECT sd.id_item_fk,sd.cantidad_autorizada,sd.cantidad,i.stock,i.nombre FROM solicitud_detalles sd JOIN inventario i ON i.id_item=sd.id_item_fk WHERE sd.id_solicitud_fk=? FOR UPDATE');$d->bind_param('i',$sid);$d->execute();$lines=$d->get_result()->fetch_all(MYSQLI_ASSOC);foreach($lines as $ln){$qty=(float)($ln['cantidad_autorizada']??0);if($qty<=0)$qty=(float)$ln['cantidad'];if($qty>(float)$ln['stock']){$db->rollback();resp(false,'Stock insuficiente para entregar: '.$ln['nombre']);}$upd=$db->prepare('UPDATE inventario SET stock=stock-? WHERE id_item=?');$upd->bind_param('di',$qty,$ln['id_item_fk']);$upd->execute();$mov=$db->prepare("INSERT INTO movimientos(id_item_fk,id_usuario_fk,tipo,cantidad,detalle) VALUES(?,?,'Salida',?,?)");$detail='Entrega de solicitud SOL-'.str_pad((string)$sid,5,'0',STR_PAD_LEFT);$mov->bind_param('iids',$ln['id_item_fk'],$uid,$qty,$detail);$mov->execute();}$u=$db->prepare("UPDATE solicitudes SET estado='Entregada',id_usuario_entrega_fk=?,fecha_entrega=NOW(),fecha_actualizacion=NOW() WHERE id_solicitud=?");$u->bind_param('ii',$uid,$sid);$u->execute();$db->commit();resp(true,'Entrega registrada y stock actualizado.');}
 if($op==='entradaStock'){rol([1,4]);$id=(int)($_POST['id']??0);$qty=(float)($_POST['cantidad']??0);$desc=trim($_POST['detalle']??'Entrada de stock');if(!$id||$qty<=0)resp(false,'Cantidad inválida.');$db->begin_transaction();$up=$db->prepare('UPDATE inventario SET stock=stock+? WHERE id_item=? AND activo=1');$up->bind_param('di',$qty,$id);$up->execute();if(!$up->affected_rows){$db->rollback();resp(false,'Artículo no encontrado.');}$m=$db->prepare("INSERT INTO movimientos(id_item_fk,id_usuario_fk,tipo,cantidad,detalle) VALUES(?,?,'Entrada',?,?)");$m->bind_param('iids',$id,$uid,$qty,$desc);$m->execute();$db->commit();resp(true,'Entrada de stock registrada.');}
 if($op==='movimientos'){rol([1,4]);$rows=$db->query('SELECT m.*,i.nombre item,i.codigo,u.nombre usuario,u.apellido FROM movimientos m JOIN inventario i ON i.id_item=m.id_item_fk JOIN usuarios u ON u.id_usuario=m.id_usuario_fk ORDER BY m.id_movimiento DESC LIMIT 100')->fetch_all(MYSQLI_ASSOC);resp(true,'Movimientos',$rows);}
 resp(false,'Operación no reconocida.');
}catch(Throwable $e){if(isset($db)){try{$db->rollback();}catch(Throwable $x){}}resp(false,'Error al procesar la operación. Revisa los datos e intenta de nuevo.');}
